#include <deque>
#include <iostream>
#include <algorithm>

int main() {
    std::deque<int> d = {10, 20, 30};

    // 1. Get a pointer and a reference to an element
    int& ref_20 = d[1]; 
    int* ptr_20 = &d[1]; 
    auto it_20 = d.begin() + 1;

    // 2. Insert at the front (O(1))
    d.push_front(5);

    // Iterators are invalid, references/pointers are valid
    // std::cout << *it_20; // DANGER: UB! Iterator invalid

    std::cout << "Reference value: " << ref_20 << "\n"; // OK: Value is 20
    std::cout << "Pointer value: " << *ptr_20 << "\n";   // OK: Value is 20

    // d.insert(d.begin() + 2, 25); // Insertion in middle
    // // ALL iterators, references, and pointers would now be invalid.
}
